<?php $title='Overview';require 'header.php';$d=db();$total=(int)$d->query("SELECT COUNT(*) c FROM disputes")->fetch_assoc()['c'];$open=(int)$d->query("SELECT COUNT(*) c FROM disputes WHERE status IN('submitted','under_review','awaiting_response')")->fetch_assoc()['c'];$urgent=(int)$d->query("SELECT COUNT(*) c FROM disputes WHERE priority='urgent' AND status NOT IN('resolved','closed')")->fetch_assoc()['c'];$resolved=(int)$d->query("SELECT COUNT(*) c FROM disputes WHERE status IN('resolved','closed')")->fetch_assoc()['c'];?>
<div class="admin-head"><div><div class="kicker"><span></span> CASE OPERATIONS</div><h1>Keep every dispute moving.</h1></div><a class="btn orange" href="cases.php">Review cases</a></div>
<div class="metrics"><div><span>Total cases</span><b><?=$total?></b></div><div><span>Open</span><b><?=$open?></b></div><div><span>Urgent</span><b><?=$urgent?></b></div><div><span>Resolved</span><b><?=$resolved?></b></div></div>
<section class="admin-panel"><div class="panel-top"><h2>Latest cases</h2><a href="cases.php">View all →</a></div><table><thead><tr><th>Case</th><th>Claimant</th><th>Type</th><th>Priority</th><th>Status</th><th></th></tr></thead><tbody><?php $st=$d->query("SELECT * FROM disputes ORDER BY created_at DESC LIMIT 10");while($r=$st->fetch_assoc()):?><tr><td class="mono"><?=h($r['case_no'])?></td><td><b><?=h($r['claimant_name'])?></b><small><?=h($r['claimant_email'])?></small></td><td><?=h($r['dispute_type'])?></td><td><span class="priority <?=h($r['priority'])?>"><?=h(ucfirst($r['priority']))?></span></td><td><span class="status <?=h($r['status'])?>"><?=h(label($r['status']))?></span></td><td><a href="case.php?id=<?=$r['id']?>">Open</a></td></tr><?php endwhile;?></tbody></table></section><?php require 'footer.php';?>